import{_ as i,a8 as e,o as l,c as r,ah as d,K as t}from"./chunks/framework.BNwxUeRp.js";import"./chunks/theme.BC7t94LL.js";const u=JSON.parse('{"title":"Jev 适用场景与局限","description":"","frontmatter":{"title":"Jev 适用场景与局限","abstract":"Jev 决策模型的适用场景与局限性分析，讲解其擅长的高频结构化判断场景、与 RAG 的组合方式及不适用的任务类型。","created":"2026-09-23T00:00:00.000Z","tags":["AI","Jev","应用场景"],"type":"概念解释","related":["[[Jev-MOC]]","[[Jev-概述]]","[[Jev-零幻觉与置信度]]","[[RAG 概述]]"],"reference":"","category":["🧩 AI框架与Agent","Jev"]},"headers":[],"relativePath":"vault/Knowledge/AI/Jev-适用场景与局限.md","filePath":"vault/Knowledge/AI/Jev-适用场景与局限.md","lastUpdated":1790655645000}'),o={name:"vault/Knowledge/AI/Jev-适用场景与局限.md"};function h(p,a,c,b,g,k){const s=e("NolebaseGitContributors"),n=e("NolebaseGitChangelog");return l(),r("div",null,[a[0]||(a[0]=d(`<h1 id="jev-适用场景与局限" tabindex="-1">Jev 适用场景与局限 <a class="header-anchor" href="#jev-适用场景与局限" aria-label="Permalink to “Jev 适用场景与局限”">​</a></h1><h2 id="判断标准" tabindex="-1">判断标准 <a class="header-anchor" href="#判断标准" aria-label="Permalink to “判断标准”">​</a></h2><p>只要一个任务可以被转换成下面任意一种形态，就可能适合 Jev：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>Yes / No      A / B / C      1 / 2 / 3 / 4 / 5      概率</span></span></code></pre></div><h2 id="典型场景" tabindex="-1">典型场景 <a class="header-anchor" href="#典型场景" aria-label="Permalink to “典型场景”">​</a></h2><h3 id="客服工单路由" tabindex="-1">客服工单路由 <a class="header-anchor" href="#客服工单路由" aria-label="Permalink to “客服工单路由”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户消息 → Jev ├─ 类型：退款</span></span>
<span class="line"><span>               ├─ 紧急度：4</span></span>
<span class="line"><span>               └─ 是否需要人工：0.87</span></span>
<span class="line"><span>        → 客服系统 → 自动分流</span></span></code></pre></div><h3 id="内容审核" tabindex="-1">内容审核 <a class="header-anchor" href="#内容审核" aria-label="Permalink to “内容审核”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>内容 → Jev ├─ 是否违规：0.97</span></span>
<span class="line"><span>           ├─ 严重程度：4/5</span></span>
<span class="line"><span>           └─ 是否人工复核：0.08</span></span></code></pre></div><p>系统按置信度分流：高置信度自动拦截，低置信度转人工。</p><h3 id="agent-工具选择" tabindex="-1">Agent 工具选择 <a class="header-anchor" href="#agent-工具选择" aria-label="Permalink to “Agent 工具选择”">​</a></h3><p>Agent 经常要回答「应该搜索 / 查数据库 / 调用 API / 直接回答」，传统做法是全部交给 LLM；Jev 可以承担工具 A / B / C 之间的快速选择。</p><h3 id="rag-结果过滤" tabindex="-1">RAG 结果过滤 <a class="header-anchor" href="#rag-结果过滤" aria-label="Permalink to “RAG 结果过滤”">​</a></h3><p>检索出来的内容并非都真正相关，可以用 Jev 充当<strong>检索之后的智能过滤层</strong>：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>用户问题 → Retriever → A 0.92 ｜ B 0.86 ｜ C 0.18 ｜ D 0.07 ｜ E 0.13</span></span>
<span class="line"><span>                          ↓ 只保留 A、B</span></span>
<span class="line"><span>                      A + B → LLM → 最终答案</span></span></code></pre></div><p>同一条路子还可用于相关性判断、文档筛选、结果重排、答案质量检查。</p><h3 id="其他典型领域" tabindex="-1">其他典型领域 <a class="header-anchor" href="#其他典型领域" aria-label="Permalink to “其他典型领域”">​</a></h3><table tabindex="0"><thead><tr><th>领域</th><th>交给 Jev 的问题</th></tr></thead><tbody><tr><td>风控</td><td>是否异常？风险等级是多少？是否需要人工？</td></tr><tr><td>销售</td><td>客户意向度多少？是否值得跟进？优先级多少？</td></tr><tr><td>文档处理</td><td>这是什么类型的文档？应该进入哪个流程？</td></tr><tr><td>发票处理</td><td>是否符合要求？是否存在异常？是否需要人工审核？</td></tr><tr><td>AI 质检</td><td>LLM 的回答是否合规？是否回答了问题？是否存在风险？</td></tr><tr><td>Agent Guardrail</td><td>这个动作是否安全？是否允许执行？是否需要审批？</td></tr></tbody></table><h2 id="不适合-jev-的任务" tabindex="-1">不适合 Jev 的任务 <a class="header-anchor" href="#不适合-jev-的任务" aria-label="Permalink to “不适合 Jev 的任务”">​</a></h2><p>写文章、写代码、长文本总结、开放式聊天、创意写作、复杂解释、开放式问答，以及任何<strong>最终需要大量自然语言输出</strong>的任务。原因很直接：这类任务要的就是文本生成，而 Jev 的设计目标恰恰是减少文本生成。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light one-dark-pro" style="--shiki-light:#24292e;--shiki-dark:#abb2bf;--shiki-light-bg:#fff;--shiki-dark-bg:#282c34;" tabindex="0" dir="ltr"><code><span class="line"><span>「写一篇退款政策说明」    → LLM</span></span>
<span class="line"><span>「这次请求是不是退款问题？」→ Jev</span></span></code></pre></div><h2 id="快速判断表" tabindex="-1">快速判断表 <a class="header-anchor" href="#快速判断表" aria-label="Permalink to “快速判断表”">​</a></h2><table tabindex="0"><thead><tr><th>你的问题</th><th>选择</th></tr></thead><tbody><tr><td>是不是？选哪个？几分？是否需要人工？下一步走哪个流程？应该调用哪个工具？是否存在风险？</td><td><strong>Jev</strong></td></tr><tr><td>请解释……请分析……请写一篇……请设计……请生成代码……请总结……请提出方案……</td><td><strong>LLM</strong></td></tr></tbody></table><h2 id="对官方指标的理性认识" tabindex="-1">对官方指标的理性认识 <a class="header-anchor" href="#对官方指标的理性认识" aria-label="Permalink to “对官方指标的理性认识”">​</a></h2><p>Jev 官方公布了低延迟、低成本，以及在官方 workflow evals 中较大的速度与成本优势。这些数字应理解为<strong>官方测试环境下的官方评测结果</strong>，不能推断成「Jev 在任何任务上都比 GPT 快几百倍」。原因包括：</p><ul><li>不同任务的计算量不同</li><li>不同模型适合的任务不同</li><li>上下文长度会显著影响结果</li><li>官方 benchmark 与真实生产环境存在差异</li></ul><p>因此评价 Jev 时应问「<strong>它是否适合某类任务</strong>」，而不是「它是否全面比 GPT 更强」——后者并不是 Jev 的产品定位。</p><p><em>（内容由AI生成，仅供参考）</em></p>`,28)),t(s),t(n)])}const _=i(o,[["render",h]]);export{u as __pageData,_ as default};
